args.old_str:
static RECT get_uvrect(stbtt_bakedchar *g, FLOAT h, FLOAT w) {
    RECT const uv_rect = {
        .x = g->x0 / w,
        .y = g->y0 / h,
        .w = (g->x1 - g->x0) / w,
        .h = (g->y1 - g->y0) / h,
    };
    return uv_rect;
}

args.new_str:
static RECT get_uvrect(stbtt_bakedchar *g, FLOAT h, FLOAT w) {
    // 确保分母不为零
    if (w <= 0.0f) w = 1.0f;
    if (h <= 0.0f) h = 1.0f;

    RECT const uv_rect = {
        .x = g->x0 / w,
        .y = g->y0 / h,
        .w = (g->x1 - g->x0) / w,
        .h = (g->y1 - g->y0) / h,
    };
    return uv_rect;
}
